head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf07201";
scwin.contnId = undefined;
scwin.parentContnId = undefined;
scwin.gRegEmpNo = undefined;
scwin.dts_ContentsDel = null;
scwin.dts_ContentsInfo = null;
scwin.dts_fileList = null;
scwin.upd_infFind = null;
scwin.pJsEmpNo = undefined;
scwin.pJsEmpNm = undefined;
scwin.pJsEmail = undefined;
scwin.fn_read = null;
scwin.fn_save = null;
scwin.fn_update = null;
scwin.fn_delete = null;
scwin.fn_SetSaveHeader = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    // TODO Stage2: 공급사 pcc 의존(저장소 pcc/fil 에 없음 · 반입 또는 치환 판단) — $c.frame.CloseFrame, $c.frame.Provider
    try {
        scwin.showObj(ipt_tboxMktTp, false);
        let parentYn = $c.win.getParent().parentContnId;
        if (parentYn == null || parentYn === "undefined" || parentYn.length === 0) {
            await $c.win.alert("선택된 질문이 없습니다.");
            $c.win.closePopup();
        } else {
            getParentContnId = $c.win.getParent().fn_getParentContnId;
            scwin.parentContnId = getParentContnId();
        }
        parentYn = $c.win.getParent().contnId;
        if (parentYn == null || parentYn === "undefined" || parentYn.length === 0) {
            scwin.contnId = "input";
        } else {
            getContnId = $c.win.getParent().fn_getContnId;
            scwin.contnId = getContnId();
        }
        scwin.fn_read();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07201.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.pJsEmpNo =$c.session.getUserInfo("empNo"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07201' }); }

try { scwin.pJsEmpNm =$c.session.getUserInfo("empNm"); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07201' }); }

try { scwin.pJsEmail =js_email; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf07201' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.dts_ContentsDel = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ContentsDel')) : $c.util.getComponent('dts_ContentsDel');
        scwin.dts_ContentsInfo = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ContentsInfo')) : $c.util.getComponent('dts_ContentsInfo');
        scwin.dts_fileList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsFileList')) : $c.util.getComponent('dtsFileList');
        scwin.upd_infFind = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_infFind') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_infFind"]');
        scwin.fn_read = scwin.sbm_trs_Read;
        scwin.fn_save = scwin.sbm_trs_Save;
        scwin.fn_update = scwin.sbm_trs_Update;
        scwin.fn_delete = scwin.sbm_trs_Delete;
        scwin.fn_SetSaveHeader = scwin.tx_script_dts_ContentsInfo;
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf07201.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
