/**
 * @method
 * @name inf_find_onclick
 * @description inf_find 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_onclick = function () {
    try {
        const filenm = scwin.dts_fileList.getCellData(scwin.dts_fileList.getRowPosition(), "filename");
        if (scwin.contnId === "input") {
            scwin.dts_fileList.setCellData(scwin.dts_fileList.getRowPosition(), "fileInfo", scwin.upd_infFind.Value);
            $c.util.getComponent("ipt_fileName").setValue(scwin.upd_infFind.Value);
        } else {
            scwin.dts_fileList.setCellData(scwin.dts_fileList.getRowPosition(), "fileInfo", scwin.upd_infFind.Value);
            scwin.dts_fileList.setCellData(scwin.dts_fileList.getRowPosition(), "ATTACH_SEQ", scwin.dts_fileList.getRowPosition());
            $c.util.getComponent("ipt_fileName").setValue(scwin.upd_infFind.Value);
        }
        if (scwin.upd_infFind.Value === "") {
            $c.util.getComponent("ipt_fileName").setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "jldstf07201.inf_find_onclick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description btn_lineadd 의 onclick 에서 dts_fileList 을(를) 행을 추가한다 외
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_lineadd_onclick = async function () {
    try {
        if (scwin.dts_fileList.countrow === 5) {
            await $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }
        scwin.dts_fileList.insertRow();
        scwin.upd_infFind.open();
        if (scwin.upd_infFind.Value !== "") {
            if (scwin.contnId === "input") {
                scwin.dts_fileList.setCellData(scwin.dts_fileList.getRowPosition(), "fileInfo", scwin.upd_infFind.Value);
                $c.util.getComponent("ipt_fileName").setValue(scwin.upd_infFind.Value);
            } else {
                scwin.dts_fileList.setCellData(scwin.dts_fileList.getRowPosition(), "fileInfo", scwin.upd_infFind.Value);
                scwin.dts_fileList.setCellData(scwin.dts_fileList.getRowPosition(), "ATTACH_SEQ", scwin.dts_fileList.getRowPosition());
                $c.util.getComponent("ipt_fileName").setValue(scwin.upd_infFind.Value);
            }
        } else {
            scwin.dts_fileList.removeRow(scwin.dts_fileList.getRowPosition());
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07201.btn_lineadd_onclick' }); }
};

