 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_fileList_onclick = async function (row, colid) {
    try {
        if (scwin.dts_fileList.getRowStatus(scwin.dts_fileList.getRowPosition()) === 0) {
            await scwin.filedown(scwin.dts_fileList.getCellData(row, "ATTACH_SEQ"));
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07201.grd_fileList_onclick' }); }
};

