    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions);
        { const dsh = (typeof scwin['trs_Delete_onloadcompleted'] === 'function') ? scwin['trs_Delete_onloadcompleted'] : ((typeof scwin['trs_Delete_onsuccess'] === 'function') ? scwin['trs_Delete_onsuccess'] : null); if (dsh) { const dsl = $c.util.getComponent('trs_Delete'); await dsh((dsl && dsl.getRowCount) ? dsl.getRowCount() : 0); } } }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldstf07201.sbm_trs_Delete" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

